using System.Net;using System.Net.Mail;using MechanicalDesigns.Application.Email;using Microsoft.Extensions.Configuration;
namespace MechanicalDesigns.Infrastructure.Email;public sealed class SmtpEmailService(IConfiguration c):IEmailService{public async Task SendAsync(string to,string subject,string body,CancellationToken ct){var host=c["Email:Host"];var user=c["Email:Username"];var pass=c["Email:Password"];if(string.IsNullOrWhiteSpace(host)||string.IsNullOrWhiteSpace(user)||string.IsNullOrWhiteSpace(pass))throw new InvalidOperationException("SMTP email secrets are not configured.");using var client=new SmtpClient(host,int.TryParse(c["Email:Port"],out var port)?port:587){EnableSsl=true,Credentials=new NetworkCredential(user,pass)};using var message=new MailMessage(user,to,subject,body);await client.SendMailAsync(message,ct);}}
